        let hd = -size.y * (qB.z - qF.z);
        let nappe = clipHalfLine(-hF, -hF - hd);
        let a = size.x * size.x * dot(xyd, xyd) - hd * hd;
        let b = size.x * size.x * dot(xyF, xyd) - hF * hd;
        let c = size.x * size.x * dot(xyF, xyF) - hF * hF;
