    let he = abs((2.0 * H.xy - H.zw) - c);
    let ve = abs((2.0 * V.xy - V.zw) - c);

    // horizontal and vertical diff with the smallest depth difference from slopes
    let hDeriv = select(r, l, he.x < he.y);
    let vDeriv = select(u, d, ve.x < ve.y);

